CREATE TABLE public.f1_trusted_ed25519_signer ("signerId" text PRIMARY KEY,"publicKey" bytea NOT NULL,"purpose" text NOT NULL,"active" boolean NOT NULL,"notBefore" timestamptz NOT NULL,"notAfter" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "f1_signer_key_check" CHECK(octet_length("publicKey")=32),CONSTRAINT "f1_signer_purpose_check" CHECK("purpose" IN('kms_hmac_subject_assertion','deployment_attestation','old_call_telemetry')),CONSTRAINT "f1_signer_window_check" CHECK("notAfter">"notBefore"));CREATE TABLE public.f1_verified_nonce ("purpose" text NOT NULL,"nonce" text NOT NULL,"operation" text NOT NULL,"idempotencyHash" text NOT NULL,"intentHash" text NOT NULL,"subjectDigest" bytea,"resultId" uuid,"expiresAt" timestamptz NOT NULL,"consumedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("purpose","nonce"),UNIQUE("operation","idempotencyHash","intentHash"));CREATE TABLE public.f1_kms_provider_allowlist("providerPrefix" text PRIMARY KEY,"purpose" text NOT NULL,"active" boolean NOT NULL,"notBefore" timestamptz NOT NULL,"notAfter" timestamptz NOT NULL,CONSTRAINT "f1_kms_window_check" CHECK("notAfter">"notBefore"));CREATE TABLE public.f1_readiness_health_source("sourceKey" text PRIMARY KEY,"healthy" boolean NOT NULL,"observedAt" timestamptz NOT NULL,"detailCode" text NOT NULL,CONSTRAINT "f1_readiness_source_key_check" CHECK("sourceKey" IN('migration','database','storage','parser','optional_provider')));CREATE TABLE public.f1_subject_erasure_tombstone("erasureToken" bytea NOT NULL,"retentionCutoff" timestamptz NOT NULL,"intentHash" text NOT NULL,"jobId" uuid NOT NULL,"requestId" text NOT NULL,"purgedRows" integer NOT NULL,"auditEventId" uuid NOT NULL REFERENCES public.audit_events(id) ON DELETE RESTRICT,"erasedAt" timestamptz NOT NULL,PRIMARY KEY("erasureToken","retentionCutoff"),CONSTRAINT f1_erasure_intent_hash_check CHECK("intentHash"~'^[0-9a-f]{64}$'));CREATE FUNCTION public.f1_reject_erasure_tombstone_mutation_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$ BEGIN RAISE EXCEPTION 'ERASURE_TOMBSTONE_IMMUTABLE';END $fn$;CREATE TRIGGER f1_erasure_tombstone_immutable BEFORE UPDATE OR DELETE ON public.f1_subject_erasure_tombstone FOR EACH ROW EXECUTE FUNCTION public.f1_reject_erasure_tombstone_mutation_v1();CREATE TABLE public.f1_p10_subject_key_provider ("kid" text PRIMARY KEY,"providerKeyRef" text NOT NULL,"epoch" text NOT NULL,"status" text NOT NULL,"activatedAt" timestamptz,"retiredAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "f1_p10_provider_ref_check" CHECK("providerKeyRef"~'^kms://[A-Za-z0-9/_:.-]{8,240}$'),CONSTRAINT "f1_p10_key_epoch_check" CHECK("epoch"='vanstro.analytics.subject-epoch.v1:'||"kid"),CONSTRAINT "f1_p10_key_status_check" CHECK(("status"='active' AND "activatedAt" IS NOT NULL AND "retiredAt" IS NULL) OR ("status"='retired_verification' AND "activatedAt" IS NOT NULL AND "retiredAt" IS NOT NULL)));CREATE UNIQUE INDEX "f1_p10_one_active_key" ON public.f1_p10_subject_key_provider(("status")) WHERE "status"='active';CREATE TABLE public.f1_p10_idempotency ("operation" text NOT NULL,"idempotencyHash" text NOT NULL,"intentHash" text NOT NULL,"subjectDigest" bytea,"resultId" uuid,"auditEventId" uuid,"state" text NOT NULL DEFAULT 'claimed',"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("operation","idempotencyHash"),CONSTRAINT "f1_p10_idem_hash_check" CHECK("idempotencyHash"~'^[0-9a-f]{64}$' AND "intentHash"~'^[0-9a-f]{64}$'),CONSTRAINT "f1_p10_idem_state_check" CHECK(("state"='claimed' AND "resultId" IS NULL AND "auditEventId" IS NULL) OR ("state"='completed' AND "subjectDigest" IS NOT NULL AND "resultId" IS NOT NULL AND "auditEventId" IS NOT NULL)));CREATE TABLE public.f1_p10_consent_command ("id" uuid PRIMARY KEY,"subjectDigest" bytea NOT NULL,"kid" text NOT NULL,"epoch" text NOT NULL,"action" text NOT NULL,"idempotencyHash" text NOT NULL UNIQUE,"intentHash" text NOT NULL,"expiresAt" timestamptz NOT NULL,"successAuditEventId" uuid NOT NULL REFERENCES public.audit_events("id") ON DELETE RESTRICT,CONSTRAINT "f1_p10_consent_action_check" CHECK("action" IN('granted','updated','withdrawn')));CREATE TABLE public.f1_p02_resolver_registry ("resourceType" text PRIMARY KEY,"resolverId" text NOT NULL UNIQUE,"tableName" text NOT NULL,"idSemantics" text NOT NULL,"operationKey" text NOT NULL,"permissionKey" text NOT NULL,CONSTRAINT "f1_p02_resolver_registry_closed_check" CHECK (("resourceType","resolverId","tableName","idSemantics","operationKey","permissionKey") IN (('p08_import','resolver.p08_import','dashboard_import_batch','uuid','read','dashboard.import.foundation_sample.read'),('p08_export','resolver.p08_export','dashboard_export_request','uuid','read','dashboard.export.foundation_sample.read'),('p09_config','resolver.p09_config','runtime_config_version','row_uuid','read','config.read'),('p09_flag','resolver.p09_flag','feature_flag_version','row_uuid','read','flags.read'),('p09_readiness_summary','resolver.p09_readiness_summary','worker_heartbeats','literal:worker-fleet','read','readiness.read_summary'),('p09_readiness_detail','resolver.p09_readiness_detail','worker_heartbeats','literal:worker-fleet','read','readiness.read_detail'),('p10_analytics_ingestion','resolver.p10_analytics_ingestion','foundation_sample','uuid','ingest','analytics.ingest'),('p10_release_family','resolver.p10_release_family','analytics_foundation_release','six-field-family','read','analytics.release.read'))));INSERT INTO public.f1_p02_resolver_registry VALUES ('p08_import','resolver.p08_import','dashboard_import_batch','uuid','read','dashboard.import.foundation_sample.read'),('p08_export','resolver.p08_export','dashboard_export_request','uuid','read','dashboard.export.foundation_sample.read'),('p09_config','resolver.p09_config','runtime_config_version','row_uuid','read','config.read'),('p09_flag','resolver.p09_flag','feature_flag_version','row_uuid','read','flags.read'),('p09_readiness_summary','resolver.p09_readiness_summary','worker_heartbeats','literal:worker-fleet','read','readiness.read_summary'),('p09_readiness_detail','resolver.p09_readiness_detail','worker_heartbeats','literal:worker-fleet','read','readiness.read_detail'),('p10_analytics_ingestion','resolver.p10_analytics_ingestion','foundation_sample','uuid','ingest','analytics.ingest'),('p10_release_family','resolver.p10_release_family','analytics_foundation_release','six-field-family','read','analytics.release.read');ALTER TABLE public.runtime_config_version ADD COLUMN "authorityVersion" smallint NOT NULL DEFAULT 1, ADD COLUMN "successAuditEventId" uuid;
ALTER TABLE public.feature_flag_version ADD COLUMN "authorityVersion" smallint NOT NULL DEFAULT 1, ADD COLUMN "successAuditEventId" uuid;
ALTER TABLE public.foundation_sample ADD COLUMN "contextRevision" text NOT NULL DEFAULT 'foundation-context.v1', ADD COLUMN "version" integer NOT NULL DEFAULT 0;ALTER TABLE public.analytics_foundation_event ADD COLUMN "authenticatedSubjectDigest" bytea, ADD COLUMN "subjectKeyVersion" text, ADD COLUMN "identityEpoch" text, ADD COLUMN "authorityVersion" smallint NOT NULL DEFAULT 1, ADD COLUMN "successAuditEventId" uuid, ADD COLUMN "postSealLate" boolean NOT NULL DEFAULT false;
ALTER TABLE public.privacy_consent_events ADD COLUMN "authenticatedSubjectDigest" bytea, ADD COLUMN "subjectKeyVersion" text, ADD COLUMN "identityRealmVersion" text, ADD COLUMN "identityEpoch" text, ADD COLUMN "consentSchemaVersion" text, ADD COLUMN "authorityVersion" smallint NOT NULL DEFAULT 1;
ALTER TABLE public.runtime_config_version ADD CONSTRAINT "runtime_config_version_success_audit_event_fkey" FOREIGN KEY ("successAuditEventId") REFERENCES public.audit_events("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "runtime_config_version_success_audit_event_key" UNIQUE ("successAuditEventId");
ALTER TABLE public.feature_flag_version ADD CONSTRAINT "feature_flag_version_success_audit_event_fkey" FOREIGN KEY ("successAuditEventId") REFERENCES public.audit_events("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "feature_flag_version_success_audit_event_key" UNIQUE ("successAuditEventId");
ALTER TABLE public.analytics_foundation_event ADD CONSTRAINT "analytics_foundation_event_success_audit_event_fkey" FOREIGN KEY ("successAuditEventId") REFERENCES public.audit_events("id") ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT "analytics_foundation_event_success_audit_event_key" UNIQUE ("successAuditEventId"), ADD CONSTRAINT "analytics_foundation_event_authenticated_tuple_check" CHECK (("authorityVersion"<2 AND "authenticatedSubjectDigest" IS NULL AND "subjectKeyVersion" IS NULL AND "identityEpoch" IS NULL) OR ("authorityVersion"=2 AND "authenticatedSubjectDigest" IS NOT NULL AND "subjectKeyVersion" IS NOT NULL AND "identityEpoch" IS NOT NULL AND octet_length("authenticatedSubjectDigest")=32 AND "subjectKeyVersion"~'^[a-z0-9][a-z0-9._-]{0,31}$' AND "identityEpoch"='vanstro.analytics.subject-epoch.v1:'||"subjectKeyVersion"));
ALTER TABLE public.privacy_consent_events ADD CONSTRAINT "privacy_consent_events_authenticated_tuple_check" CHECK (("authorityVersion"<2 AND "authenticatedSubjectDigest" IS NULL AND "subjectKeyVersion" IS NULL AND "identityRealmVersion" IS NULL AND "identityEpoch" IS NULL AND "consentSchemaVersion" IS NULL) OR ("authorityVersion"=2 AND "authenticatedSubjectDigest" IS NOT NULL AND "subjectKeyVersion" IS NOT NULL AND "identityRealmVersion" IS NOT NULL AND "identityEpoch" IS NOT NULL AND "consentSchemaVersion" IS NOT NULL AND octet_length("authenticatedSubjectDigest")=32 AND "identityRealmVersion"='vanstro.authenticated-user.v1' AND "consentSchemaVersion"='vanstro.analytics.authenticated-consent.v1' AND "identityEpoch"='vanstro.analytics.subject-epoch.v1:'||"subjectKeyVersion"));

CREATE TABLE public.analytics_foundation_release (
 "id" uuid PRIMARY KEY,"scopeFingerprint" text NOT NULL,"releaseDay" date NOT NULL,"metricDefinitionVersion" text NOT NULL,"identityEpoch" text NOT NULL,"suppressionPolicyVersion" text NOT NULL,"fieldVisibilityProfile" text NOT NULL,"authorizationScopeKind" text NOT NULL DEFAULT 'global',"status" text NOT NULL,"completeness" text NOT NULL,"sourceCutoff" timestamptz NOT NULL,"sealedAt" timestamptz NOT NULL,"lateExcludedCount" bigint NOT NULL DEFAULT 0,"authorityVersion" smallint NOT NULL DEFAULT 2,"successAuditEventId" uuid NOT NULL,
 CONSTRAINT "analytics_foundation_release_success_audit_event_fkey" FOREIGN KEY ("successAuditEventId") REFERENCES public.audit_events("id") ON DELETE RESTRICT ON UPDATE CASCADE,
 CONSTRAINT "analytics_foundation_release_success_audit_event_key" UNIQUE ("successAuditEventId"),
 CONSTRAINT "analytics_foundation_release_family_key" UNIQUE ("scopeFingerprint","releaseDay","metricDefinitionVersion","identityEpoch","suppressionPolicyVersion","fieldVisibilityProfile"),
 CONSTRAINT "analytics_foundation_release_state_check" CHECK ("authorizationScopeKind"='global' AND "status" IN ('empty','suppressed','published') AND "completeness" IN ('sealed','late_excluded') AND "authorityVersion"=2 AND "sourceCutoff"=("releaseDay"::timestamp AT TIME ZONE 'UTC')+interval '1 day 10 minutes' AND "sealedAt">="sourceCutoff" AND "lateExcludedCount">=0)
);
CREATE TABLE public.analytics_foundation_release_event("releaseId" uuid NOT NULL REFERENCES public.analytics_foundation_release(id) ON DELETE RESTRICT,"eventId" uuid NOT NULL REFERENCES public.analytics_foundation_event(id) ON DELETE RESTRICT,PRIMARY KEY("releaseId","eventId"));CREATE TABLE public.analytics_foundation_release_cell (
 "id" uuid PRIMARY KEY,"releaseId" uuid NOT NULL,"cellKey" text NOT NULL,"state" text NOT NULL,"valueKind" text NOT NULL,"denominatorDistinct" bigint,"numeratorDistinct" bigint,"complementDistinct" bigint,"publishedValue" numeric,"completeness" text NOT NULL,
 CONSTRAINT "analytics_foundation_release_cell_release_fkey" FOREIGN KEY ("releaseId") REFERENCES public.analytics_foundation_release("id") ON DELETE RESTRICT ON UPDATE CASCADE,
 CONSTRAINT "analytics_foundation_release_cell_key" UNIQUE ("releaseId","cellKey"),
 CONSTRAINT "analytics_foundation_release_cell_privacy_state_check" CHECK (("state"='empty' AND "denominatorDistinct"=0 AND "numeratorDistinct"=0 AND "complementDistinct"=0 AND "publishedValue" IS NULL) OR ("state"='suppressed' AND "denominatorDistinct" IS NULL AND "numeratorDistinct" IS NULL AND "complementDistinct" IS NULL AND "publishedValue" IS NULL) OR ("state"='published' AND ("denominatorDistinct"=0 OR "denominatorDistinct">=3) AND ("numeratorDistinct"=0 OR "numeratorDistinct">=3) AND ("complementDistinct"=0 OR "complementDistinct">=3) AND "numeratorDistinct"+"complementDistinct"="denominatorDistinct" AND "publishedValue">=0))
);
